package com.dappunq.controller; import com.dappunq.dto.valuation.*; import com.dappunq.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/users/{usuarioId}") public class ValuationControllerRest { final StrategyConfigurationService strategies; final HoldingsValuationService holdings; public ValuationControllerRest(StrategyConfigurationService s,HoldingsValuationService h){strategies=s;holdings=h;} @PutMapping("/strategy") public StrategyStateResponse put(@PathVariable Long usuarioId,@Valid @RequestBody StrategyRequest r){return strategies.configure(usuarioId,r);} @GetMapping("/strategy") public StrategyStateResponse get(@PathVariable Long usuarioId){return strategies.get(usuarioId);} @GetMapping("/holdings") public List<HoldingResponse> holdings(@PathVariable Long usuarioId){return holdings.list(usuarioId);} @GetMapping("/holdings/history") public List<HoldingHistoryResponse> history(@PathVariable Long usuarioId){return holdings.history(usuarioId);} }
